// Fractal Noise (fBm) - Ray Marching
// Rumore frattale: 3 ottave di value-noise 3D sul punto di hit pModel.
// Sfuma tra i due colori del dock: u_col2 = valli, u_col1 = creste.
// NB: in questo tab il codice gira DENTRO shadeSurface() -> niente definizioni
// di funzioni e niente macro fragili: tutto scritto esteso e inline.
// Variabili engine: pModel, n_model, ubuf.u_time, ubuf.u_col1/u_col2.

// SCALA: alza il 2.5 per un frattale piu' fitto. Lo scorrimento anima il campo.
vec3 fp = pModel * 2.5 + vec3(0.0, 0.0, ubuf.u_time * 0.08);

float nfbm = 0.0;
float amp  = 0.5;
float norm = 0.0;

// 3 ottave: ad ogni giro raddoppio la frequenza e dimezzo l'ampiezza.
for (int oct = 0; oct < 3; oct++) {
    vec3 ip = floor(fp);
    vec3 fr = fract(fp);
    vec3 w  = fr * fr * (3.0 - 2.0 * fr);   // smoothstep per la trilineare

    // hash dei 4 spigoli alla quota z=0 e z=1 (value noise 3D)
    float h000 = fract(sin(dot(ip + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h100 = fract(sin(dot(ip + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h010 = fract(sin(dot(ip + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h110 = fract(sin(dot(ip + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h001 = fract(sin(dot(ip + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h101 = fract(sin(dot(ip + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h011 = fract(sin(dot(ip + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h111 = fract(sin(dot(ip + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);

    float z0 = mix(mix(h000, h100, w.x), mix(h010, h110, w.x), w.y);
    float z1 = mix(mix(h001, h101, w.x), mix(h011, h111, w.x), w.y);
    float vn = mix(z0, z1, w.z);

    nfbm += amp * vn;
    norm += amp;
    fp   *= 2.0;   // ottava successiva
    amp  *= 0.5;
}
nfbm /= norm;   // normalizza ~[0,1]

// contrasto: stringi gli estremi per creste piu' nette
float tfbm = smoothstep(0.25, 0.75, nfbm);

// COLORI DEL DOCK: u_col2 nelle valli, u_col1 sulle creste
textureCol = mix(ubuf.u_col2, ubuf.u_col1, tfbm);
